import { test, expect } from '@playwright/test';

test.describe('Cancel In-Progress Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');
  });

  test('should display cancel button during file upload', async ({ page }) => {
    // Find and interact with file input
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);

    // Create a large dummy file to ensure upload takes time
    const largeFile = new File(['x'.repeat(10 * 1024 * 1024)], 'large-file.txt', { type: 'text/plain' });

    await fileInput.setInputFiles(largeFile);

    // Wait for upload to start
    await page.waitForTimeout(500);

    // Verify cancel button is visible
    const cancelButton = page.getByRole('button', { name: /cancel|stop upload/i });
    await expect(cancelButton).toBeVisible();
  });

  test('should cancel upload when cancel button is clicked', async ({ page }) => {
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);

    // Create a large dummy file
    const largeFile = new File(['y'.repeat(10 * 1024 * 1024)], 'large-file-2.txt', { type: 'text/plain' });

    await fileInput.setInputFiles(largeFile);

    // Wait for upload to start
    await page.waitForTimeout(500);

    // Click cancel button
    const cancelButton = page.getByRole('button', { name: /cancel|stop upload/i });
    await cancelButton.click();

    // Verify upload was cancelled - check for cancellation message or state
    const cancelledMessage = page.getByText(/upload cancelled|upload stopped|cancelled/i);
    await expect(cancelledMessage).toBeVisible({ timeout: 5000 });
  });

  test('should reset upload form after cancellation', async ({ page }) => {
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);

    const largeFile = new File(['z'.repeat(10 * 1024 * 1024)], 'large-file-3.txt', { type: 'text/plain' });

    await fileInput.setInputFiles(largeFile);

    // Wait for upload to start
    await page.waitForTimeout(500);

    // Cancel the upload
    const cancelButton = page.getByRole('button', { name: /cancel|stop upload/i });
    await cancelButton.click();

    // Wait for cancellation to complete
    await page.waitForTimeout(1000);

    // Verify cancel button is no longer visible
    const cancelButtonAfter = page.getByRole('button', { name: /cancel|stop upload/i });
    await expect(cancelButtonAfter).not.toBeVisible();

    // Verify upload progress is reset
    const progressBar = page.getByRole('progressbar');
    if (await progressBar.isVisible()) {
      const progressValue = await progressBar.getAttribute('aria-valuenow');
      expect(parseInt(progressValue || '0')).toBe(0);
    }
  });

  test('should allow new upload after cancelling previous one', async ({ page }) => {
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);

    // First upload attempt
    const largeFile1 = new File(['a'.repeat(10 * 1024 * 1024)], 'file-1.txt', { type: 'text/plain' });
    await fileInput.setInputFiles(largeFile1);

    await page.waitForTimeout(500);

    // Cancel first upload
    const cancelButton = page.getByRole('button', { name: /cancel|stop upload/i });
    await cancelButton.click();

    await page.waitForTimeout(1000);

    // Second upload attempt with different file
    const smallFile = new File(['small content'], 'small-file.txt', { type: 'text/plain' });
    await fileInput.setInputFiles(smallFile);

    // Verify new upload started
    const uploadButton = page.getByRole('button', { name: /upload|submit/i });
    await expect(uploadButton).toBeEnabled();
  });
});
